<?php declare(strict_types=1); $d=$record??$old??[]; $base=config('app.base_path'); $selectedRestaurant=(int)($d['restaurant_id']??0); ?><div class="card"><div class="form-grid"><div class="form-group"><label>Restaurant <span class="required">*</span></label><select name="restaurant_id" id="restaurant_id" required><option value="">Select restaurant...</option><?php foreach(($restaurants??[]) as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $selectedRestaurant===(int)$r['id']?'selected':'' ?>><?= htmlspecialchars((string)$r['business_name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Category</label><select name="category_id" id="category_id"><option value="">Uncategorized</option><?php foreach(($all_categories??[]) as $c): ?><option data-restaurant="<?= (int)$c['restaurant_id'] ?>" value="<?= (int)$c['id'] ?>" <?= (string)($d['category_id']??'')===(string)$c['id']?'selected':'' ?>><?= htmlspecialchars((string)$c['restaurant_name'].' — '.$c['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Name <span class="required">*</span></label><input name="name" required value="<?= htmlspecialchars((string)($d['name']??''),ENT_QUOTES,'UTF-8') ?>"></div><div class="form-group"><label>Slug</label><input name="slug" value="<?= htmlspecialchars((string)($d['slug']??''),ENT_QUOTES,'UTF-8') ?>" placeholder="auto-generated if blank"></div><div class="form-group"><label>Price <span class="required">*</span></label><input type="number" step="0.01" min="0" name="price" required value="<?= htmlspecialchars((string)($d['price']??'0.00'),ENT_QUOTES,'UTF-8') ?>"></div><div class="form-group"><label>Discount</label><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><select name="discount_type"><option value="PERCENT" <?= ($d['discount_type']??'PERCENT')==='PERCENT'?'selected':'' ?>>Percent (%)</option><option value="FLAT" <?= ($d['discount_type']??'PERCENT')==='FLAT'?'selected':'' ?>>Flat (₹)</option></select><input type="number" step="0.01" min="0" name="discount_value" value="<?= htmlspecialchars((string)($d['discount_value']??'0.00'),ENT_QUOTES,'UTF-8') ?>" placeholder="0"></div><small style="color:#64748b">Example: ₹200 + 5% = ₹190 selling price.</small></div><div class="form-group"><label>Sort Order</label><input type="number" name="sort_order" value="<?= (int)($d['sort_order']??0) ?>"></div><div class="form-group"><label>Status</label><select name="status"><option>Active</option><option <?= ($d['status']??'')==='Inactive'?'selected':'' ?>>Inactive</option></select></div><div class="form-group"><label><input type="checkbox" name="is_veg" value="1" <?= !empty($d['is_veg'])?'checked':'' ?>> Vegetarian</label><label><input type="checkbox" name="is_available" value="1" <?= !isset($d['is_available'])||!empty($d['is_available'])?'checked':'' ?>> Available for ordering</label></div><div class="form-group full-width"><label>Description</label><textarea name="description" rows="4"><?= htmlspecialchars((string)($d['description']??''),ENT_QUOTES,'UTF-8') ?></textarea></div><div class="form-group full-width"><label>Image Path</label><input name="image_path" value="<?= htmlspecialchars((string)($d['image_path']??''),ENT_QUOTES,'UTF-8') ?>"></div></div></div><script>(function(){const r=document.getElementById('restaurant_id'),c=document.getElementById('category_id');function f(){const v=r.value;[...c.options].forEach(o=>{if(!o.value)return;o.hidden=o.dataset.restaurant!==v;o.disabled=o.hidden;});if(c.selectedOptions[0]?.disabled)c.value='';}r.addEventListener('change',f);f();})();</script>
